def union_days(intervals, year):
    if len(intervals) == 0:
        return 0
    ordered = sorted(intervals)
    current_start = ordered[0][0]
    current_end = ordered[0][1]
    total = 0
    i = 1
    while i < len(ordered):
        start = ordered[i][0]
        end = ordered[i][1]
        if start <= current_end:
            current_end = max(current_end, end)
        else:
            total += inclusive_year_overlap_days(current_start, current_end, year)
            current_start = start
            current_end = end
        i += 1
    return total + inclusive_year_overlap_days(current_start, current_end, year)


